"""Actions tab — renders an HTML actions page from the filesystem.

Displays an HTML file from ~/source/personal-assistant/. Refreshed
by the Assistant tab's refresh button, not independently.
"""

from __future__ import annotations

import tkinter as tk
from typing import Any

from personal_assistant.config import (
    ACTIONS_HTML,
    BG_OUTPUT,
    BG_WINDOW,
    COLOR_BUTTON,
    COLOR_BUTTON_ACTIVE,
    COLOR_HTML_FALLBACK_BG,
    COLOR_HTML_FALLBACK_FG,
    FG_DIM,
    FG_TEXT,
    FONT_NAME_BODY,
    PAD,
)

# Import spacing CSS from assistant_tab
from personal_assistant.assistant_tab import SPACING_CSS


class ActionsTab:
    """Actions tab — renders HTML from the filesystem."""

    def __init__(self, parent: tk.Frame) -> None:
        self._parent = parent
        self._html_frame: Any = None
        self._build()

    def _build(self) -> None:
        # Control bar with status + reload button
        controls = tk.Frame(self._parent, bg=BG_WINDOW)
        controls.pack(fill=tk.X, padx=PAD, pady=(PAD, 0))

        self._status_var = tk.StringVar(value="")
        tk.Label(
            controls,
            textvariable=self._status_var,
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=FONT_NAME_BODY,
        ).pack(side=tk.LEFT)

        tk.Button(
            controls,
            text="\U0001f504",
            command=self.refresh,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_NAME_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=4,
        ).pack(side=tk.RIGHT)

        try:
            from tkinterweb import HtmlFrame

            import webbrowser

            self._html_frame = HtmlFrame(
                self._parent,
                messages_enabled=False,
                dark_theme_enabled=True,
                on_link_click=lambda url: webbrowser.open(url),
            )
            self._html_frame.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            self.refresh()
        except ImportError:
            fallback = tk.Text(
                self._parent,
                bg=BG_OUTPUT,
                fg=FG_TEXT,
                font=FONT_NAME_BODY,
                wrap=tk.WORD,
                state=tk.DISABLED,
                highlightthickness=0,
            )
            fallback.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)
            fallback.configure(state=tk.NORMAL)
            fallback.insert(
                "1.0",
                "tkinterweb not installed. Run: pip install tkinterweb[recommended]",
            )
            fallback.configure(state=tk.DISABLED)

    def set_status(self, text: str) -> None:
        """Update the status label (called by AssistantTab)."""
        self._status_var.set(text)

    def set_font_scale(self, scale: float) -> None:
        """Apply font scaling to the HTML frame via CSS."""
        self._font_scale_css = f"body {{ font-size: {scale * 100:.0f}%; }}"
        if self._html_frame is not None:
            self._html_frame.add_css(self._font_scale_css)

    def refresh(self) -> None:
        """Reload the HTML file."""
        if self._html_frame is None:
            return
        if ACTIONS_HTML.exists():
            content = ACTIONS_HTML.read_text(encoding="utf-8")
            self._html_frame.load_html(content)
            self._html_frame.add_css(SPACING_CSS)
            if hasattr(self, "_font_scale_css"):
                self._html_frame.add_css(self._font_scale_css)
        else:
            self._html_frame.load_html(
                f"<html><body style='background:{COLOR_HTML_FALLBACK_BG};"
                f"color:{COLOR_HTML_FALLBACK_FG};"
                f"font-family:sans-serif;padding:20px'>"
                f"<p>No actions page found at:</p>"
                f"<code>{ACTIONS_HTML}</code></body></html>"
            )

    def on_destroy(self) -> None:
        """Called during dashboard shutdown to clean up resources."""
        pass
